/* SIS Agent World — static mock.
 * Local-only: no fetch/XHR/WebSocket, no storage, no credentials, no backend.
 * Everything lives in memory for the life of the page.
 * Body data is loaded from the generated dist/world-data.js (loaded before this
 * script in world.html; generated by tools/sync-world-data.js).
 */
(function () {
  "use strict";

  // ---- Mock data ---------------------------------------------------------
  var rooms = [
    { id: "receiving", name: "Receiving" },
    { id: "processing", name: "Processing" },
    { id: "cold", name: "Cold Storage" },
    { id: "dispatch", name: "Dispatch" },
    { id: "workshop", name: "Workshop" },
    { id: "charge", name: "Charge Bay" }
  ];

  var agents = [
    { id: "VCT-01", name: "Victor", role: "orchestrator", room: "dispatch", state: "working", body: null },
    { id: "ORC-02", name: "Orchard", role: "data-clerk", room: "processing", state: "working", body: "ORCHARD-01" },
    { id: "SPK-03", name: "Sparky", role: "courier", room: "dispatch", state: "idle", body: "SPARKY-02" },
    { id: "LTS-04", name: "Lotus", role: "ball-scout", room: "workshop", state: "idle", body: null }
  ];

  // Body data — single source of truth. Generated from
  // sis-victor-pass/world/bodies.json into dist/world-data.js by
  // tools/sync-world-data.js and consumed here; no hardcoded copy.
  var bodies = (window.SIS_WORLD_DATA && window.SIS_WORLD_DATA.bodies) || [];
  if (!bodies.length && typeof console !== "undefined" && console.warn) {
    console.warn("SIS world: no body data — is dist/world-data.js loaded before world.js?");
  }

  var selectedAgentId = null;
  var moveTimers = {};

  // ---- Helpers -----------------------------------------------------------
  function byId(list, id) {
    for (var i = 0; i < list.length; i++) if (list[i].id === id) return list[i];
    return null;
  }
  function agentIn(bodyId) {
    for (var i = 0; i < agents.length; i++) if (agents[i].body === bodyId) return agents[i];
    return null;
  }
  function occupantsOf(roomId) {
    var out = [];
    for (var i = 0; i < agents.length; i++) if (agents[i].room === roomId) out.push(agents[i]);
    return out;
  }
  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }
  function log(msg) {
    var el = document.getElementById("log");
    if (!el) return;
    var row = document.createElement("div");
    var t = document.createElement("time");
    var now = new Date();
    t.textContent = String(now.getHours()).padStart(2, "0") + ":" +
                    String(now.getMinutes()).padStart(2, "0") + ":" +
                    String(now.getSeconds()).padStart(2, "0");
    row.appendChild(t);
    row.appendChild(document.createTextNode(msg));
    el.insertBefore(row, el.firstChild);
  }
  function setStatus(msg) {
    var el = document.getElementById("status");
    if (el) el.textContent = msg;
  }

  // ---- Render ------------------------------------------------------------
  function renderRooms() {
    var host = document.getElementById("roomGrid");
    if (!host) return;
    host.textContent = "";
    rooms.forEach(function (room) {
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "room";
      btn.dataset.room = room.id;
      var sel = selectedAgentId ? byId(agents, selectedAgentId) : null;
      btn.setAttribute("aria-pressed", sel && sel.room === room.id ? "true" : "false");
      btn.setAttribute("aria-label", "Move selected agent to " + room.name);

      var name = document.createElement("span");
      name.className = "rname";
      name.textContent = room.name;
      btn.appendChild(name);

      var occ = document.createElement("span");
      occ.className = "occupants";
      var people = occupantsOf(room.id);
      if (people.length === 0) {
        var e = document.createElement("span");
        e.className = "token empty";
        e.textContent = "empty";
        occ.appendChild(e);
      } else {
        people.forEach(function (a) {
          var tok = document.createElement("span");
          tok.className = "token";
          tok.textContent = a.name;
          occ.appendChild(tok);
        });
      }
      btn.appendChild(occ);
      btn.addEventListener("click", function () { moveTo(room.id); });
      host.appendChild(btn);
    });
  }

  function renderAgents() {
    var host = document.getElementById("agentList");
    if (!host) return;
    host.textContent = "";
    agents.forEach(function (a) {
      var li = document.createElement("li");
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "agent";
      btn.dataset.agent = a.id;
      btn.setAttribute("aria-pressed", a.id === selectedAgentId ? "true" : "false");

      var who = document.createElement("span");
      who.className = "who";
      var nm = document.createElement("span");
      nm.textContent = a.name;
      var rl = document.createElement("small");
      rl.textContent = a.role + " · " + roomName(a.room);
      who.appendChild(nm);
      who.appendChild(rl);
      btn.appendChild(who);

      var badge = document.createElement("span");
      badge.className = "badge " + a.state;
      badge.textContent = a.state;
      btn.appendChild(badge);

      btn.addEventListener("click", function () { selectAgent(a.id); });
      li.appendChild(btn);
      host.appendChild(li);
    });
  }

  function roomName(id) {
    var r = byId(rooms, id);
    return r ? r.name : id;
  }

  function renderDetail() {
    var el = document.getElementById("agentDetail");
    if (!el) return;
    var a = selectedAgentId ? byId(agents, selectedAgentId) : null;
    if (!a) { el.textContent = "No agent selected."; return; }
    var b = a.body ? byId(bodies, a.body) : null;
    el.innerHTML =
      "<b>" + esc(a.name) + "</b> (" + esc(a.id) + ")<br>" +
      "role: " + esc(a.role) + "<br>" +
      "room: " + esc(roomName(a.room)) + "<br>" +
      "state: " + esc(a.state) + "<br>" +
      "body: " + (b ? esc(b.id) + " / " + esc(b.klass) : "<i>none</i>");
  }

  function renderBodies() {
    var host = document.getElementById("bodyList");
    if (!host) return;
    host.textContent = "";
    bodies.forEach(function (b) {
      var li = document.createElement("li");
      li.className = "body";

      var row = document.createElement("div");
      row.className = "brow";
      var id = document.createElement("span");
      id.textContent = b.id;
      var holder = agentIn(b.id);
      var badge = document.createElement("span");
      badge.className = "badge " + (holder ? "assigned" : "free");
      badge.textContent = holder ? "assigned · " + holder.name : "free";
      row.appendChild(id);
      row.appendChild(badge);
      li.appendChild(row);

      var caps = document.createElement("div");
      caps.className = "caps";
      caps.textContent = b.klass + " · " + b.caps.join(", ");
      li.appendChild(caps);

      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "assign";
      var sel = selectedAgentId ? byId(agents, selectedAgentId) : null;
      var mine = sel && sel.body === b.id;
      btn.textContent = mine ? "unassign" : "assign";
      btn.disabled = !sel;
      btn.dataset.body = b.id;
      btn.addEventListener("click", function () {
        if (mine) { unassignBody(b.id); } else { assignBody(b.id); }
      });
      li.appendChild(btn);

      host.appendChild(li);
    });
  }

  function render() {
    renderRooms();
    renderAgents();
    renderDetail();
    renderBodies();
  }

  // ---- Interactions (local only) ----------------------------------------
  function selectAgent(id) {
    selectedAgentId = (selectedAgentId === id) ? null : id;
    if (selectedAgentId) {
      var a = byId(agents, selectedAgentId);
      setStatus("Selected " + a.name + ". Pick a room to move, or a body to assign.");
      log("select " + a.name + " (" + a.id + ")");
    } else {
      setStatus("Selection cleared.");
      log("deselect");
    }
    render();
  }

  function moveTo(roomId) {
    var a = selectedAgentId ? byId(agents, selectedAgentId) : null;
    if (!a) { setStatus("Select an agent first, then pick a room."); return; }
    if (a.room === roomId) { setStatus(a.name + " is already in " + roomName(roomId) + "."); return; }
    var from = a.room;
    a.room = roomId;
    a.state = "moving";
    setStatus(a.name + " moving " + roomName(from) + " → " + roomName(roomId) + ".");
    log("move " + a.name + ": " + roomName(from) + " → " + roomName(roomId));
    render();
    if (moveTimers[a.id]) clearTimeout(moveTimers[a.id]);
    moveTimers[a.id] = setTimeout(function () {
      if (a.state === "moving") { a.state = a.body ? "working" : "idle"; render(); }
    }, 900);
  }

  function assignBody(bodyId) {
    var a = selectedAgentId ? byId(agents, selectedAgentId) : null;
    if (!a) { setStatus("Select an agent first, then assign a body."); return; }
    var b = byId(bodies, bodyId);
    if (!b) return;
    var holder = agentIn(bodyId);
    if (holder && holder.id !== a.id) {
      // single-holder rule: detach from the previous owner
      holder.body = null;
      holder.state = holder.state === "working" ? "idle" : holder.state;
      log("detach " + b.id + " from " + holder.name);
    }
    if (a.body && a.body !== bodyId) log("swap " + a.name + " out of " + a.body);
    a.body = bodyId;
    if (a.state !== "moving") a.state = "working";
    setStatus(a.name + " assigned body " + b.id + " (" + b.klass + ").");
    log("assign " + b.id + " → " + a.name);
    render();
  }

  function unassignBody(bodyId) {
    var a = agentIn(bodyId);
    if (!a) return;
    a.body = null;
    if (a.state === "working") a.state = "idle";
    setStatus(a.name + " released body " + bodyId + ".");
    log("unassign " + bodyId + " from " + a.name);
    render();
  }

  // ---- Boot --------------------------------------------------------------
  function init() {
    if (!document.getElementById("roomGrid")) return; // not the world page
    render();
    log("world ready — " + rooms.length + " rooms, " + agents.length + " agents, " + bodies.length + " bodies");
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }

  // Exposed for local smoke checks only (no network).
  window.SISWorld = {
    select: selectAgent,
    move: moveTo,
    assign: assignBody,
    unassign: unassignBody,
    snapshot: function () {
      return {
        selected: selectedAgentId,
        agents: agents.map(function (a) { return { id: a.id, room: a.room, state: a.state, body: a.body }; }),
        bodies: bodies.map(function (b) {
          var h = agentIn(b.id);
          return { id: b.id, holder: h ? h.id : null };
        })
      };
    }
  };
})();
